import{_ as o,c as i,a as d,o as c}from"./app-C_dHcy8Q.js";const l={};function r(a,e){return c(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="wire-di-providers" tabindex="-1"><a class="header-anchor" href="#wire-di-providers"><span>Wire DI &amp; Providers</span></a></h1><p>This document summarizes the dependency injection setup using Google Wire and the available providers.</p><h2 id="entry-points" tabindex="-1"><a class="header-anchor" href="#entry-points"><span>Entry Points</span></a></h2><ul><li><code>InitServerApp(...)</code>: compose a Server from explicit dependencies (audit writer, RBAC policy, JWT manager, db, repos, services, etc.)</li><li><code>InitServerAppAuto(...)</code>: auto-construct audit/RBAC/JWT/DB/Repos/Services from environment variables</li></ul><h2 id="providers" tabindex="-1"><a class="header-anchor" href="#providers"><span>Providers</span></a></h2><ul><li>DB: <code>ProvideGormDBFromEnv()</code><ul><li><code>DB_DRIVER</code>: <code>postgres|mysql|sqlite|mssql|sqlserver|auto</code> (default <code>auto</code>)</li><li><code>DATABASE_URL</code>: connection string/DSN</li><li>Auto fallback to SQLite: <code>file:data/croupier.db</code></li></ul></li><li>Games defaults: <code>ProvideGamesDefaults()</code> → reads <code>configs/games.json</code> (<code>default_envs</code>)</li><li>RBAC policy: <ul><li><code>ProvideRBACPolicyAuto()</code><ul><li>If both <code>RBAC_MODEL</code> and <code>RBAC_POLICY</code> are set, use Casbin with these paths</li><li>Else use <code>RBAC_CONFIG</code> (JSON or Casbin directory); JSON falls back to legacy policy</li></ul></li></ul></li><li>JWT manager: <code>ProvideJWTManagerFromEnv()</code><ul><li><code>JWT_SECRET</code>: HS256 secret (default <code>dev-secret</code>)</li></ul></li><li>Certificate store: <code>ProvideCertStore(db)</code> (GORM-backed)</li><li>Object store: <code>ProvideObjectStoreFromEnv()</code><ul><li><code>STORAGE_DRIVER</code>: <code>s3|file|oss|cos</code></li><li><code>STORAGE_BUCKET</code>, <code>STORAGE_REGION</code>, <code>STORAGE_ENDPOINT</code>, <code>STORAGE_ACCESS_KEY</code>, <code>STORAGE_SECRET_KEY</code>, <code>STORAGE_FORCE_PATH_STYLE</code></li><li><code>file</code> mode defaults to <code>data/uploads</code> when base dir is empty</li></ul></li><li>ClickHouse: <code>ProvideClickHouseFromEnv()</code><ul><li><code>CLICKHOUSE_DSN</code>: e.g., <code>clickhouse://host:port/...</code> (optional)</li></ul></li></ul><h2 id="local-development" tabindex="-1"><a class="header-anchor" href="#local-development"><span>Local Development</span></a></h2><ul><li>Install wire: <code>go install github.com/google/wire/cmd/wire@latest</code></li><li>Generate code: <code>make wire</code> (runs <code>wire</code> in <code>internal/app/server/http</code>)</li><li>Commit generated file: <code>internal/app/server/http/wire_gen.go</code> (CI validates no diff)</li></ul><h2 id="notes" tabindex="-1"><a class="header-anchor" href="#notes"><span>Notes</span></a></h2><ul><li>Handlers should be thin: decode → authorize → call service → encode</li><li>Services should depend only on ports, not GORM</li><li>Repositories (GORM) own DB models and perform persistence only</li></ul>',10)])])}const s=o(l,[["render",r]]),n=JSON.parse('{"path":"/wire-and-di.html","title":"Wire DI & Providers","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1762699203000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"131875167feba215d595f088f163e7468dc20883","time":1762699203000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"chore: sync"}]},"filePathRelative":"wire-and-di.md"}');export{s as comp,n as data};
